        "solutionBlocks": [
          {
            "id": "block-15-4-sol",
            "type": "text",
            "content": "$\\lim _{x \\rightarrow 0} \\frac{\\sin a x-\\sin b x}{\\sin c x}=\\lim _{x \\rightarrow 0} \\frac{\\frac{\\sin a x}{a b c x}-\\frac{\\sin b x}{a b c x}}{\\frac{\\sin c x}{a b c x}}=\\frac{\\frac{1}{b c}-\\frac{1}{a c}}{\\frac{1}{a b}}=\\frac{a-b}{c}$"
          }
        ]
