        "correctOption": 2,
        "choiceType": "single",
        "hintBlocks": [],
        "solutionBlocks": [
          {
            "id": "block-16-1-sol",
            "type": "text",
            "content": "$\\begin{aligned} & \\lim _{x \\rightarrow 0} \\frac{\\ln (x+a)-\\ln a}{x}=\\lim _{x \\rightarrow 0} \\frac{1}{x} \\ln \\frac{x+a}{a}=\\lim _{x \\rightarrow 0} \\ln \\left(\\frac{x+a}{a}\\right)^{\\frac{a}{x} \\frac{1}{a}} \\\\ & =\\ln e^{\\frac{1}{a}}=\\frac{1}{a}\\end{aligned}$"
          }
        ]
