        "choiceType": "single",
        "hintBlocks": [],
        "solutionBlocks": [
          {
            "id": "block-16-4-sol",
            "type": "text",
            "content": "$\\begin{aligned} & \\lim _{x \\rightarrow \\infty}\\left(\\frac{2 x-1}{2 x+1}\\right)^{2 x-1}=\\lim _{x \\rightarrow \\infty}\\left(1-\\frac{2}{2 x+1}\\right)^{-\\frac{2 x+1}{2} \\frac{-2(2 x-1)}{2 x+1}} \\\\ & =e^{\\lim _{x \\rightarrow \\infty} \\frac{-2(2 x-1)}{2 x+1}}=e^{-2}\\end{aligned}$"
          }
        ]
