        "solutionBlocks": [
          {
            "id": "block-16-16-sol",
            "type": "text",
            "content": "$\\begin{aligned} \\lim _{x \\rightarrow e} \\frac{\\ln x-1}{x-e} & =\\lim _{x \\rightarrow e} \\frac{\\ln x-\\ln e}{x-e}=\\lim _{x \\rightarrow e} \\ln \\left(\\frac{x}{e}\\right)^{\\frac{1}{x-e}} \\\\ & =\\lim _{x \\rightarrow e} \\ln \\left(1+\\frac{x-e}{e}\\right)^{\\frac{e}{x-e} \\cdot \\frac{1}{e}}=\\frac{1}{e} \\end{aligned}$"
          }
        ]
