        "solutionBlocks": [
          {
            "id": "block-56-6-sol",
            "type": "text",
            "content": "$\\begin{aligned} & \\lim _{x \\rightarrow 0} \\frac{e^x-1-x}{\\sqrt{1-x}-\\cos \\sqrt{x}} \\\\ = & \\lim _{x \\rightarrow 0} \\frac{\\left(1+x+\\frac{x^2}{2}+o\\left(x^2\\right)\\right)-1-x}{\\left(1-\\frac{x}{2}-\\frac{x^2}{8}+o\\left(x^2\\right)\\right)-\\left(1-\\frac{x}{2}+\\frac{x^2}{4!}+o\\left(x^2\\right)\\right)} \\\\ = & \\lim _{x \\rightarrow 0} \\frac{\\frac{x^2}{2}+o\\left(x^2\\right)}{-\\frac{x^2}{6}+o\\left(x^2\\right)}=-3 .\\end{aligned}$"
          }
        ]
