// Helper: merge with existing StaticQuestion format (strip _meta)
export function getChapterById(id: string): StaticQuestionBankChapter | undefined {
  return advancedMathExerciseChapters.find(c => c.id === id);
}

export function getChaptersByRange(startIdx: number, count?: number): StaticQuestionBankChapter[] {
  if (count === undefined) return advancedMathExerciseChapters.slice(startIdx);
  return advancedMathExerciseChapters.slice(startIdx, startIdx + count);
}

export const totalExercises = advancedMathExerciseChapters.reduce(
  (sum, ch) => sum + ch.questions.length, 0
);

// ============================================================
// 大章节分组结构
// ============================================================

// 大章节定义
export interface AdvancedMathMajorChapter {
  id: string;
  title: string;
  icon: string;
  chapterNum: number;
}

export const majorChapters: AdvancedMathMajorChapter[] = [
  { id: 'ch1', title: '第一章 极限与连续', icon: 'lim', chapterNum: 1 },
  { id: 'ch2', title: '第二章 导数与微分', icon: "f'", chapterNum: 2 },
  { id: 'ch3', title: '第三章 微分中值定理与导数的应用', icon: 'ξ', chapterNum: 3 },
  { id: 'ch4', title: '第四章 积分及其应用', icon: '∫', chapterNum: 4 },
  { id: 'ch5', title: '第五章 无穷级数', icon: 'Σ', chapterNum: 5 },
  { id: 'ch6', title: '第六章 向量代数与空间解析几何', icon: '→', chapterNum: 6 },
  { id: 'ch7', title: '第七章 多元函数的微分及其应用', icon: '∂', chapterNum: 7 },
  { id: 'ch8', title: '第八章 重积分', icon: '∬', chapterNum: 8 },
  { id: 'ch9', title: '第九章 曲线积分与曲面积分', icon: '∮', chapterNum: 9 },
  { id: 'ch10', title: '第十章 常微分方程', icon: "y'", chapterNum: 10 },
];

// 子章节号(原始文件编号) -> 大章节号 映射
export const chapterToMajorChapter: Record<string, number> = {
  // 第一章 极限与连续
  '2': 1, '4': 1, '5': 1, '7': 1, '8': 1, '9': 1, '10': 1,
  '12': 1, '13': 1, '15': 1, '16': 1, '17': 1, '19': 1, '20': 1,
  '21': 1, '22': 1, '23': 1, '24': 1,
  // 第二章 导数与微分
  '27': 2, '28': 2, '29': 2, '30': 2, '32': 2, '33': 2, '34': 2,
  '36': 2, '37': 2, '39': 2, '40': 2, '42': 2, '44': 2, '45': 2,
  '46': 2, '47': 2,
  // 第三章 微分中值定理与导数的应用
  '50': 3, '51': 3, '52': 3, '54': 3, '55': 3, '56': 3, '58': 3,
  // 第四章 积分及其应用
  '41': 4,
  // 第四章~第十章: 暂无子章节数据
};

// 根据大章节号获取子章节
export function getChaptersByMajor(majorNum: number): StaticQuestionBankChapter[] {
  return advancedMathExerciseChapters.filter(
    ch => chapterToMajorChapter[ch.id.replace('adv-ch-', '')] === majorNum
  );
}

// 按大章节组织的树形结构
export function getGroupedChapters(): { major: AdvancedMathMajorChapter; chapters: StaticQuestionBankChapter[] }[] {
  return majorChapters.map(major => ({
    major,
    chapters: getChaptersByMajor(major.chapterNum),
  }));
}
